using System.Net;
using System.Text;
using System.Text.RegularExpressions;
using HtmlAgilityPack;
namespace Keynote.Online;
/// <summary>Reads the public Mutopia search form's HTML; it is not a documented JSON API.</summary>
public sealed class MutopiaCatalogProvider(HttpClient http) : IMidiCatalogProvider {
 readonly SemaphoreSlim throttle=new(1,1); DateTimeOffset lastRequest=DateTimeOffset.MinValue;
 static string Text(HtmlNode? n)=>WebUtility.HtmlDecode(n?.InnerText ?? "").Replace('\u00a0',' ').Trim();
 static Uri? MidiUri(string raw) { if(!Uri.TryCreate(raw,UriKind.Absolute,out var uri) || !(uri.Scheme=="https"||uri.Scheme=="http") || !(uri.Host.Equals("www.mutopiaproject.org",StringComparison.OrdinalIgnoreCase)||uri.Host.Equals("mutopiaproject.org",StringComparison.OrdinalIgnoreCase)) || !uri.IsDefaultPort || !string.IsNullOrEmpty(uri.UserInfo) || !string.IsNullOrEmpty(uri.Query) || !string.IsNullOrEmpty(uri.Fragment) || !uri.AbsolutePath.StartsWith("/ftp/",StringComparison.Ordinal) || !uri.AbsolutePath.EndsWith(".mid",StringComparison.OrdinalIgnoreCase))return null; return new UriBuilder(uri){Scheme="https",Port=-1}.Uri; }
 public async Task<CatalogPage> SearchAsync(string query,int page,CancellationToken token) {
  if(page<0 || page>10000)throw new ArgumentOutOfRangeException(nameof(page)); if(string.IsNullOrWhiteSpace(query))return new(Array.Empty<CatalogResult>(),false); if(query.Length>200)throw new ArgumentException("Search is limited to 200 characters.");
  await throttle.WaitAsync(token); try { var delay=TimeSpan.FromSeconds(1)-(DateTimeOffset.UtcNow-lastRequest); if(delay>TimeSpan.Zero)await Task.Delay(delay,token); lastRequest=DateTimeOffset.UtcNow; } finally { throttle.Release(); }
  var uri=$"https://www.mutopiaproject.org/cgibin/make-table.cgi?searchingfor={Uri.EscapeDataString(query.Trim())}&startat={page*10}"; using var response=await http.GetAsync(uri,HttpCompletionOption.ResponseHeadersRead,token); response.EnsureSuccessStatusCode(); if(response.Content.Headers.ContentLength>2*1024*1024)throw new InvalidDataException("Mutopia catalogue page is too large."); await using var source=await response.Content.ReadAsStreamAsync(token); using var bytes=new MemoryStream(); var block=new byte[8192]; int n; while((n=await source.ReadAsync(block,token))>0) { if(bytes.Length+n>2*1024*1024)throw new InvalidDataException("Mutopia catalogue page is too large."); bytes.Write(block,0,n); }
  var doc=new HtmlDocument(); doc.LoadHtml(Encoding.UTF8.GetString(bytes.ToArray())); var tables=doc.DocumentNode.SelectNodes("//table[contains(concat(' ',normalize-space(@class),' '),' result-table ')]"); var results=new List<CatalogResult>();
  if(tables==null && !Text(doc.DocumentNode).Contains("no matches were found",StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Mutopia catalogue format changed; open the official website.");
  if(tables!=null) foreach(var table in tables) { token.ThrowIfCancellationRequested(); var rows=table.SelectNodes(".//tr"); if(rows==null || rows.Count<4)continue; var first=rows[0].SelectNodes("./td"); var second=rows[1].SelectNodes("./td"); var third=rows[2].SelectNodes("./td"); if(first==null||first.Count<2||third==null||third.Count<3)continue; var piece=third[2].SelectSingleNode(".//a[@href]"); var match=Regex.Match(piece?.GetAttributeValue("href","")??"",@"^piece-info\.cgi\?id=(\d{1,10})$",RegexOptions.CultureInvariant,TimeSpan.FromMilliseconds(100)); if(!match.Success)continue; var id=match.Groups[1].Value; var link=table.SelectNodes(".//a[@href]")?.Select(a=>MidiUri(a.GetAttributeValue("href",""))).FirstOrDefault(u=>u!=null); var title=Text(first[0]); if(string.IsNullOrEmpty(title))continue; var artist=Text(first[1]); var description=string.Join(" | ",new[]{Text(first.ElementAtOrDefault(2)),Text(second?.ElementAtOrDefault(0)),Text(second?.ElementAtOrDefault(2))}.Where(x=>!string.IsNullOrWhiteSpace(x) && x!="n/a")); var license=Text(third[1]); if(string.IsNullOrWhiteSpace(license))license="License not stated; check the piece page.";
   results.Add(new CatalogResult("Mutopia",id,title,string.IsNullOrEmpty(artist)?"Unknown":artist,description,license,$"https://www.mutopiaproject.org/cgibin/piece-info.cgi?id={id}",DirectUrl:link?.AbsoluteUri)); }
  if(tables!=null && results.Count==0)throw new InvalidDataException("Mutopia catalogue entries could not be read; open the official website.");
  bool next=doc.DocumentNode.SelectNodes("//a[@href]")?.Any(a=>Text(a).StartsWith("Next ",StringComparison.OrdinalIgnoreCase) && a.GetAttributeValue("href","").StartsWith("make-table.cgi?startat=",StringComparison.OrdinalIgnoreCase))??false;
  return new(results.DistinctBy(x=>x.Id).ToArray(),next);
 }
 public Uri DownloadUri(CatalogResult result) { if(result.Provider!="Mutopia" || string.IsNullOrEmpty(result.DirectUrl))throw new NotSupportedException("This piece has no direct MIDI link in the public catalogue."); return MidiUri(result.DirectUrl) ?? throw new InvalidDataException("Invalid Mutopia MIDI link."); }
}
